  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Tocainide, a 2,6-dimethylanilide analogue, showed 100% absolute oral bioavailability in healthy subjects, supporting high F for the query's similar anilide core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Metolazone, a sulfamoyl-chloro-substituted diuretic, is approximately 100% bioavailable orally, supporting high F for the query's sulfonamide diuretic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Recainam, another 2,6-dimethylphenyl amide/urea antiarrhythmic, had mean absolute bioavailability of 84% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Hydrochlorothiazide, a sulfonamide diuretic with a chlorinated sulfamoylbenzene, showed 66–75% absolute oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Meclofenamate, a chlorinated N-aryl anthranilic acid, has bioavailability above 85% in humans, supporting high F for the chlorinated aromatic amide/acid motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Vismodegib, a chlorophenyl sulfonyl benzamide, had 31.8% absolute oral bioavailability, still above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 2,6-dimethylsalicylanilide sulfonamide diuretic; the closest high-transfer analogues (tocainide, metolazone, recainam, hydrochlorothiazide, meclofenamate) all show absolute oral bioavailability ≥60%, and even lower-end analogues such as vismodegib remain ≥20%, so F ≥20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself.",
    "Bupropion records are conflicting and not used as a reliable anchor.",
    "Furosemide acyl glucuronide is a metabolite and not directly comparable to the parent-like query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

